def insert_suffix_before_extension(names, suffix):
    result = []
    for name in names:
        sep_idx = max(name.rfind('/'), name.rfind('\\'))
        tail = name[sep_idx + 1:] if sep_idx != -1 else name
        dot_idx = tail.rfind('.')
        if dot_idx > 0:
            new_tail = tail[:dot_idx] + suffix + tail[dot_idx:]
            result.append((name[:sep_idx + 1] + new_tail) if sep_idx != -1 else new_tail)
        else:
            result.append(name)
    return result
